void lexo(char *s,int n)
{
    int i,j,k;
    char temp,*s2;
    s2=(char*)malloc(n*sizeof(char));
    for(i=(n-1);i>0;i--)
    {
        if(*(s+i)>*(s+i-1))
        {
            j=i;
            temp=*(s+i);
            *(s+i)=*(s+i-1);
            *(s+i+1)=temp;
            break;
        }
        else
        {
            temp=*(s+i);
            *(s+i)=*(s+i-1);
            *(s+i-1)=temp;
        }
    }
    if(i==0)
    {
        printf("No Answer");
        return;
    }
    else
    {
        for(k=0;k<(n-i-1);k++)
        {
            *(s2+k)=*(s+i+k+1);
        }
        for(k=0;k<(n-i-1);k++)
        {
            *(s+i+1+k)=*(s2+n-i-1-1-k);
        }
    }
        printf("%s",s);
}
