void sort(char* st,int len)
{
    int a,b;
    for(a=0;a<len;a++)
    {
        int pos=a;
        char sm=*(st+a);
        for(b=a+1;b<len;b++)
        {
            if(*(st+b)<*(st+a))
            {
                sm=*(st+b);
                pos=b;
            }
        }
        char temp=*(st+a);
        *(st+a)=sm;
        *(st+pos)=temp;
    }
}
